// Literal port of the team's Casa3DSDK (module cars). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from './kernel-types.js';

export function installCars(K: Kernel, shared: Shared): void {
  const { THREE, FLEET, _Y } = K;
  // ===== fleet cars (vehicles/light fleet): model per style and seed (paint colour), merged by material (1 mesh per material signature) =====
  const CARS = [];
   // {x,y,z,ry,w,d,k,seed,parent}
  // car kinds per style: ids of the fleet (@adatechnology/game-vehicles-fleet); cfg.carKinds replaces the list of a style
  const CAR_BY_STYLE = Object.assign({
    budget: ['boxy_hatch', 'entry_hatch', 'beetle', 'family_hatch', 'rideshare_hatch'],
    mid: ['compact_hatch', 'rideshare_hatch', 'turbo_hatch', 'midsize_sedan', 'fastback_sedan', 'compact_suv', 'family_hatch'],
    high: ['electric_hatch', 'hybrid_suv', 'midsize_suv', 'v8_coupe', 'large_suv', 'midsize_pickup', 'crossover_pickup', 'fastback_sedan'],
  }, K.cfg.carKinds);

  const CAR_CACHE = new Map();
  function materialSignature(m) {
    const f = v => (v == null ? '' : typeof v === 'number' ? v.toFixed(3) : v.isColor ? v.getHexString() : v.uuid || String(v));
    return [m.type, f(m.color), f(m.roughness), f(m.metalness), f(m.opacity), m.transparent ? 1 : 0, m.side, f(m.map), f(m.emissive), f(m.emissiveIntensity), m.vertexColors ? 1 : 0, m.flatShading ? 1 : 0, f(m.envMapIntensity), f(m.alphaTest)].join('|');
  }
  const BUCKETS = new Map();
  function bucketMaterial(m) {
    if (m.type !== 'MeshStandardMaterial' || m.map || m.alphaTest || m.vertexColors || !m.color) return null;
    const mt = m.metalness > 0.5 ? 2 : m.metalness > 0.2 ? 1 : 0, rg = m.roughness < 0.3 ? 0 : m.roughness < 0.6 ? 1 : 2, tr = m.transparent || m.opacity < 1, op = tr ? Math.max(0.2, Math.min(0.9, Math.round(m.opacity * 5) / 5)) : 1, sig = 'bucket' + mt + rg + 's' + m.side + (tr ? 't' + op : '');
    let b = BUCKETS.get(sig); if (!b) { b = { sig, mat: new THREE.MeshStandardMaterial({ vertexColors: true, side: m.side, transparent: tr, opacity: op, depthWrite: !tr, metalness: [0.05, 0.4, 0.8][mt], roughness: [0.22, 0.45, 0.8][rg], envMap: m.envMap || null, envMapIntensity: m.envMapIntensity != null ? m.envMapIntensity : 1 }) }; BUCKETS.set(sig, b); }
    if (!b.mat.envMap && m.envMap) b.mat.envMap = m.envMap;
    return b;
  }
  function carModel(k, seed) { // built once per key: geometry merged by material (signature), +z axis in front, centre at x/z = 0, floor at y = 0
    const kc = k + '|' + shared.quality + '|' + (seed || 0); if (CAR_CACHE.has(kc)) return CAR_CACHE.get(kc);
    if (!FLEET) return null;
    let res = null;
    try {
      const v0 = FLEET.build(k, { quality: shared.quality, seed: seed || 0 }), c = { root: v0.group, g: v0.group }; c.root.updateMatrixWorld(true); // fleet: 'high' in the viewer, 'game' (<= 6 materials) in the game
      const inv = new THREE.Matrix4(); // identity: the fleet already comes out with +z in front
      const byMaterial = new Map(), tmp = new THREE.Matrix4(), v = new THREE.Vector3(), nm = new THREE.Matrix3(), bb = new THREE.Box3();
      c.g.traverse(o => {
        if (!o.isMesh || o.isInstancedMesh || o.isSkinnedMesh || !o.geometry || !o.geometry.attributes.position) return;
        for (let p = o; p; p = p.parent) if (p.visible === false) return;
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        let geo = o.geometry; if (geo.index) geo = geo.toNonIndexed();
        if (!geo.attributes.normal) { geo = geo.clone(); geo.computeVertexNormals(); }
        tmp.multiplyMatrices(inv, o.matrixWorld); nm.getNormalMatrix(tmp);
        const pa = geo.attributes.position, na = geo.attributes.normal, ua = geo.attributes.uv, total = pa.count;
        const grs = Array.isArray(o.material) && o.geometry.groups.length ? o.geometry.groups : [{ start: 0, count: total, materialIndex: 0 }];
        for (const gr of grs) {
          const m = mats[gr.materialIndex] || mats[0]; if (!m) continue;
          const a0 = Math.min(gr.start, total), n0 = Math.min(gr.count, total - a0) - (Math.min(gr.count, total - a0) % 3); if (n0 < 3) continue;
          const P = new Float32Array(n0 * 3), N = new Float32Array(n0 * 3), U = new Float32Array(n0 * 2);
          for (let i = 0; i < n0; i++) {
            v.fromBufferAttribute(pa, a0 + i).applyMatrix4(tmp); P[i * 3] = v.x; P[i * 3 + 1] = v.y; P[i * 3 + 2] = v.z; bb.expandByPoint(v);
            v.fromBufferAttribute(na, a0 + i).applyMatrix3(nm).normalize(); N[i * 3] = v.x; N[i * 3 + 1] = v.y; N[i * 3 + 2] = v.z;
            if (ua) { U[i * 2] = ua.getX(a0 + i); U[i * 2 + 1] = ua.getY(a0 + i); }
          }
          const r: any = { P, N, U, I: null }; // simple merge per material, without simplifying or dropping pieces (bumpers, headlights and grille stay whole)
          const bk = bucketMaterial(m); if (bk) r.color = m.color; // plain opaque ones: one material per shine class, colour per vertex
          const sig = bk ? bk.sig : materialSignature(m); let G = byMaterial.get(sig); if (!G) byMaterial.set(sig, G = { m: bk ? bk.mat : m, list: [], vc: !!bk }); G.list.push(r);
        }
      });
      const parts = [];
      for (const { m, list, vc } of byMaterial.values()) {
        let nv = 0, ni = 0; for (const e of list) { nv += e.P.length / 3; ni += e.I ? e.I.length : e.P.length / 3; }
        const P = new Float32Array(nv * 3), N = new Float32Array(nv * 3), U = new Float32Array(nv * 2), I = new Uint32Array(ni); let ov = 0, oi = 0;
        for (const e of list) { const n = e.P.length / 3; P.set(e.P, ov * 3); N.set(e.N, ov * 3); U.set(e.U, ov * 2); if (e.I) for (let q = 0; q < e.I.length; q++) I[oi++] = e.I[q] + ov; else for (let q = 0; q < n; q++) I[oi++] = ov + q; ov += n; }
        const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(P, 3)); g.setAttribute('normal', new THREE.BufferAttribute(N, 3)); g.setAttribute('uv', new THREE.BufferAttribute(U, 2)); g.setIndex(new THREE.BufferAttribute(I.subarray(0, oi), 1));
        if (vc) { const C = new Float32Array(nv * 3); let q = 0; for (const e of list) { const n = e.P.length / 3, cr = e.color; for (let i = 0; i < n; i++, q++) { C[q * 3] = cr.r; C[q * 3 + 1] = cr.g; C[q * 3 + 2] = cr.b; } } g.setAttribute('color', new THREE.BufferAttribute(C, 3)); }
        g.userData.shared = true; parts.push({ geo: g, mat: m });
      }
      const cx = (bb.min.x + bb.max.x) / 2, cz = (bb.min.z + bb.max.z) / 2, y0 = bb.min.y;
      for (const p of parts) { p.geo.translate(-cx, -y0, -cz); p.geo.computeBoundingSphere(); p.geo.computeBoundingBox(); }
      if (v0.release) v0.release(); res = { damageables: v0.damageables || [], off: [cx, y0, cz], parts, W: bb.max.x - bb.min.x, L: bb.max.z - bb.min.z, H: bb.max.y - bb.min.y, tris: parts.reduce((a, p) => a + p.geo.index.count / 3, 0) };
    } catch (e) { console.warn('car ' + k, e); res = null; }
    CAR_CACHE.set(kc, res); return res;
  }
  function carGroup(k, w, d, seed) {
    const mod = carModel(k, seed); if (!mod) return null;
    const s = Math.min(1, d / mod.L, Math.max(0.5, w - 0.05) / mod.W);
    const g = new THREE.Group(); g.name = 'car:' + k; g.scale.setScalar(s);
    for (const p of mod.parts) { const m = new THREE.Mesh(p.geo, p.mat); m.castShadow = !p.mat.transparent; m.receiveShadow = true; m.renderOrder = p.mat.transparent ? 2 : 0; m.name = 'car/' + k; g.add(m); }
    return g;
  }
  function assembleCars(groups) {
    if (shared.quality === 'game') return assembleMergedCars(groups);
    for (const C of CARS) {
      const g = carGroup(C.k, C.w, C.d, C.seed); if (!g) continue;
      g.position.set(C.x, C.y, C.z); g.rotation.y = C.ry || 0;
      (groups[C.parent] || (groups[C.parent] = new THREE.Group())).add(g);
    }
  }
  // 'game' quality: all the house's cars merged into one mesh per (parent group, material signature); each car's transform goes into the vertices
  function assembleMergedCars(groups) {
    const m4 = new THREE.Matrix4(), qy = new THREE.Quaternion(), sc = new THREE.Vector3(), ps = new THREE.Vector3(), nm = new THREE.Matrix3(), v = new THREE.Vector3(), by = new Map();
    for (const C of CARS) {
      const mod = carModel(C.k, C.seed); if (!mod) continue;
      const s = Math.min(1, C.d / mod.L, Math.max(0.5, C.w - 0.05) / mod.W);
      m4.compose(ps.set(C.x, C.y, C.z), qy.setFromAxisAngle(_Y, C.ry || 0), sc.setScalar(s)); nm.getNormalMatrix(m4);
      for (const p of mod.parts) {
        const pa = p.geo.attributes.position, na = p.geo.attributes.normal, ua = p.geo.attributes.uv, ca = p.geo.attributes.color, key = C.parent + '|' + materialSignature(p.mat) + (ca ? '|vc' : '');
        let B = by.get(key); if (!B) by.set(key, B = { parent: C.parent, mat: p.mat, P: [], N: [], U: [], Cc: [], I: [], nv: 0 });
        for (let i = 0; i < pa.count; i++) {
          v.fromBufferAttribute(pa, i).applyMatrix4(m4); B.P.push(v.x, v.y, v.z); v.fromBufferAttribute(na, i).applyMatrix3(nm).normalize(); B.N.push(v.x, v.y, v.z);
          B.U.push(ua ? ua.getX(i) : 0, ua ? ua.getY(i) : 0); if (ca) B.Cc.push(ca.getX(i), ca.getY(i), ca.getZ(i));
        }
        const ix = p.geo.index.array; for (let i = 0; i < ix.length; i++) B.I.push(B.nv + ix[i]); B.nv += pa.count;
      }
    }
    for (const B of by.values()) {
      const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(B.P, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(B.N, 3)); g.setAttribute('uv', new THREE.Float32BufferAttribute(B.U, 2));
      if (B.Cc.length) g.setAttribute('color', new THREE.Float32BufferAttribute(B.Cc, 3)); g.setIndex(B.I); g.computeBoundingSphere(); g.computeBoundingBox();
      const m = new THREE.Mesh(g, B.mat); m.castShadow = !B.mat.transparent; m.receiveShadow = true; m.renderOrder = B.mat.transparent ? 2 : 0; m.name = 'cars/' + B.parent;
      (groups[B.parent] || (groups[B.parent] = new THREE.Group())).add(m);
    }
  }
  Object.assign(K, { CARS, CAR_BY_STYLE, CAR_CACHE, materialSignature, BUCKETS, bucketMaterial, carModel, carGroup, assembleCars, assembleMergedCars });
}
